import{_ as a,C as r,o as n,c as i,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"Migration Safety Requires Executed Conformance, Not Merely Correct Output","description":"","frontmatter":{"title":"Migration Safety Requires Executed Conformance, Not Merely Correct Output","date":"2026-08-09","column":"open-source-engineering","category":"daily","summary":"A persisted-state migration can preserve visible output while breaking the mechanism that was supposed to keep replay bounded. Governed migration requires readers that understand every supported historical representation and CI evidence that the shared conformance suite actually executes against each governed backend.","item_id":"Q-20260809-03","source_research_object":"research/analysis/Q-20260809-03-executed-conformance-migration-safety.md","source_reading_result":"research/reading/Q-20260809-03-checkpoint-conformance-migration.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-09-executed-conformance-migration-safety-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-09-executed-conformance-migration-safety.md","filePath":"en/engineering/2026-08-09-executed-conformance-migration-safety.md","lastUpdated":1787407830000}'),c={name:"en/engineering/2026-08-09-executed-conformance-migration-safety.md"};function l(d,e,h,u,p,m){const t=r("ArticleCover");return n(),i("div",null,[o(t,{image:"/assets/covers/daily-2026-08-09-executed-conformance-migration-safety-cover-v2.jpg",kicker:"Open-source Engineering · Daily Research",title:"Migration Safety Requires Executed Conformance, Not Merely Correct Output",summary:"A persisted-state migration can preserve visible output while breaking the mechanism that was supposed to keep replay bounded. Governed migration requires readers that understand every supported historical representation and CI evidence that the shared conformance suite actually executes against each governed backend.",version:"Q-20260809-03",status:"Daily Runtime V5 · 2026-08-09",languageHref:"/zh/engineering/2026-08-09-executed-conformance-migration-safety",languageLabel:"中文"}),e[0]||(e[0]=s(' # Migration Safety Requires Executed Conformance, Not Merely Correct Output <p>The most deceptive persisted-state migration defects do not necessarily corrupt the final value. A reader can miss a valid historical seed, replay every write from the root and still reconstruct the same additive result. The user sees correct output while the promised bounded-replay mechanism, latency profile and storage access invariant have failed.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>Migration safety is both a reader-compatibility contract over historical representations and an execution fact about conformance on real backends.</strong></p><p>Fixing only the current writer cannot repair data already stored in older forms. Keeping a conformance test file in the repository does not prove that the relevant backend installed its dependency, instantiated the backend and executed the cases. When an architecture promises bounded replay or bounded query work, that performance property is part of correctness.</p><p>The sole analytical input is the <code>Q-20260809-03</code> Research Object. Production did not perform an independent database benchmark.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This article is based on <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-03-executed-conformance-migration-safety.md" target="_blank" rel="noreferrer">Research Object — Executed Conformance for Migration Safety</a>. Its evidence trail is <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-03-checkpoint-conformance-migration.md" target="_blank" rel="noreferrer">Reading Result — Checkpoint Conformance and Persisted-State Migration</a>.</p><p>The concrete defect occurred in persisted delta-history seed lookup. Historical values could reside inline in <code>channel_values</code> or externally in <code>checkpoint_blobs</code>. The earlier lookup relied on a marker and could therefore miss a migrated plain-value seed.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>When the seed was missed, the system could start from empty state and replay the full write history. For an additive reducer, the final list still matched the expected value. An output-only assertion therefore failed to expose the regression in the intended mechanism.</p><p>The Research Object preserves these implementation facts:</p><ul><li>the repaired reader inspects both blob and inline storage locations;</li><li>seed resolution uses a real blob when present and otherwise the inline value;</li><li>a writer-only marker change would not repair checkpoints already on disk;</li><li><code>None</code> is not treated as a seed because null and absence cannot be distinguished reliably at that layer;</li><li>direct regression tests cover plain values, snapshots, version bumps and inline primitives;</li><li>the selected implementation reports Postgres conformance improving from 6/8 to 8/8;</li><li>a shared conformance file may silently skip for a backend when its dependency is missing.</li></ul><h2 id="safety-layer-comparison" tabindex="-1">Safety-layer comparison <a class="header-anchor" href="#safety-layer-comparison" aria-label="Permalink to &quot;Safety-layer comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check layer</th><th style="text-align:right;">Detects wrong output</th><th style="text-align:right;">Detects historical-form incompatibility</th><th style="text-align:right;">Detects replay-complexity regression</th><th style="text-align:right;">Proves backend coverage</th></tr></thead><tbody><tr><td>Value-only unit test</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Not necessarily</td><td style="text-align:right;">No</td><td style="text-align:right;">No</td></tr><tr><td>Backend-local regression test</td><td style="text-align:right;">Yes</td><td style="text-align:right;">For known cases</td><td style="text-align:right;">Can</td><td style="text-align:right;">One backend only</td></tr><tr><td>Shared conformance file exists</td><td style="text-align:right;">In theory</td><td style="text-align:right;">In theory</td><td style="text-align:right;">Depends on assertions</td><td style="text-align:right;">No; it may skip</td></tr><tr><td>Conformance actually runs per backend</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Can encode it explicitly</td><td style="text-align:right;">Yes</td></tr></tbody></table><p>The table is a Research Center testing-governance synthesis based on the Research Object.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Migration compatibility is first a reader responsibility. A new writer controls only future representation. It cannot retroactively convert every historical plain value, blob, marker or old schema. A marker added to new writes can make future records healthy while old records continue to trigger pathological reads.</p><p>The second issue is that test presence and test execution are different facts. A conformance file in source control does not prove CI installed the required package, constructed the target backend and ran all cases. <code>importorskip</code> is appropriate for optional capabilities, but if a backend is a governed implementation, a silent skip should be reported as missing coverage rather than success.</p><p>The third issue is that performance can be a correctness property. The purpose of a delta channel is to avoid replaying from root on every read. If work grows linearly with thread length, the architecture contract is broken even when the reconstructed value is correct. Replay count, query count or scan bounds should therefore appear in assertions.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>CodeFlowMu and Research Runtime should preserve historical fixtures for every supported result representation: flat narrative fields, structured narrative objects, legacy metric names and string or object evidence/artifacts. Validator and Markdown-projection changes should execute against those fixtures rather than testing only the newest writer output.</p><p>A Digital Employee WorkOrder store should similarly document which historical representations remain readable, the repair scan bound and worst-case replay cost. “The value can be read” and “the reader still satisfies the design invariant” are separate claims.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The selected defect is specific to the Postgres path. The Reading Result states that SQLite stores and inspects values differently and is not affected by the same mechanism. The latency and replay figures are maintainer-reported tests rather than an independent Research Center production benchmark.</p><p>The conclusion is not that every backend must share one internal representation. It is that every governed backend must satisfy the same executable external semantics and critical invariants.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next questions are which conformance cases must be non-skippable release gates, how CI should distinguish Not Run from Pass, how replay/query complexity should be encoded across backends, and how schema-version metadata should guide historical reader paths.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual shows inline and blob historical representations feeding a migration-aware reader, followed by conformance that actually executes against governed backends. The bottom statement emphasizes that correct output is not sufficient evidence of migration-invariant safety.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-03-executed-conformance-migration-safety.md" target="_blank" rel="noreferrer">Research Object — Executed Conformance for Migration Safety</a>: sole analytical input.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-03-checkpoint-conformance-migration.md" target="_blank" rel="noreferrer">Reading Result — Checkpoint Conformance and Persisted-State Migration</a>: traceability for implementation facts, reported tests, limitations and open questions.</li></ol>',32))])}const y=a(c,[["render",l]]);export{f as __pageData,y as default};
